B.Xo=new A.b1("luke-lesson-5","path-luke","\ubd80\ub974\uc2ec\uacfc \uc21c\uc885","\ub204\uac00\ubcf5\uc74c 5\uc7a5","\uc608\uc218\ub2d8\uc740 \uc5b4\ubd80\ub4e4\uc744 \ubd80\ub974\uc2dc\uace0 \uadf8\ub4e4\uc740 \ubaa8\ub4e0 \uac83\uc744 \ub0b4\ub824\ub193\uace0 \ub530\ub974\uc138\uc694. \ubca0\ub4dc\ub85c\ub294 \uc790\uc2e0\uc758 \ubd80\uc871\ud568\uc744 \uae68\ub2eb\uace0 \uc608\uc218\ub2d8 \uc55e\uc5d0 \uc5ce\ub4dc\ub824\uc694.","\ub098\ub294 \uc608\uc218\ub2d8\uc758 \ubd80\ub974\uc2ec\uc5d0 \uc5b4\ub5bb\uac8c \ubc18\uc751\ud558\uace0 \uc788\ub098\uc694?")
B.Xx=new A.b1("luke-lesson-6","path-luke","\ud558\ub098\ub2d8 \ub098\ub77c\uc758 \uae30\uc900\uacfc \uc0b6","\ub204\uac00\ubcf5\uc74c 6\uc7a5","\uc608\uc218\ub2d8\uc740 \uc548\uc2dd\uc77c\uc5d0 \ub300\ud574 \uac00\ub974\uce58\uc2dc\uba70 \ud615\uc2dd\ubcf4\ub2e4 \uc0ac\ub78c\uc744 \uc0b4\ub9ac\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4\uace0 \ub9d0\uc500\ud558\uc138\uc694. \uc5f4\ub450 \uc81c\uc790\ub97c \uc138\uc6b0\uc2dc\uace0 \ud558\ub098\ub2d8 \ub098\ub77c\uc758 \uae30\uc900\uc744 \uac00\ub974\uce58\uc138\uc694.","\ub098\ub294 \uc5b4\ub5a4 \uae30\uc900\uc73c\ub85c \uc0b4\uc544\uac00\uace0 \uc788\ub098\uc694?")
B.X4=new A.b1("luke-lesson-7","path-luke","\ubbff\uc74c\uacfc \uc0ac\ub791\uc758 \ubc18\uc751","\ub204\uac00\ubcf5\uc74c 7\uc7a5","\ubc31\ubd80\uc7a5\uc740 \ub9d0\uc500\ub9cc\uc73c\ub85c\ub3c4 \uce58\uc720\ud558\uc2e4 \uac83\uc744 \ubbff\ub294 \ud070 \ubbff\uc74c\uc744 \ubcf4\uc5ec\uc918\uc694. \uc608\uc218\ub2d8\uc740 \uacfc\ubd80\uc758 \uc544\ub4e4\uc744 \uc0b4\ub9ac\uc2dc\uba70 \uae0d\ud73c\uc744 \ub098\ud0c0\ub0b4\uc138\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\uc744 \uc5bc\ub9c8\ub098 \uc2e0\ub8b0\ud558\uace0 \uc788\ub098\uc694?")
B.Xq=new A.b1("luke-lesson-8","path-luke","\ub9d0\uc500\uacfc \ubbff\uc74c\uc758 \ubc18\uc751","\ub204\uac00\ubcf5\uc74c 8\uc7a5","\uc528 \ubfcc\ub9ac\ub294 \ube44\uc720\ub97c \ud1b5\ud574 \ub9c8\uc74c \uc0c1\ud0dc\uc5d0 \ub530\ub77c \ub9d0\uc500\uc774 \ub2e4\ub974\uac8c \ubc1b\uc544\ub4e4\uc5ec\uc9c4\ub2e4\uace0 \uac00\ub974\uce58\uc138\uc694. \ud3ed\ud48d\uc744 \uc7a0\uc7a0\ud558\uac8c \ud558\uc2dc\uba70 \ubbff\uc74c\uc744 \uac00\ub974\uce58\uc2dc\uace0 \uadc0\uc2e0 \ub4e4\ub9b0 \uc0ac\ub78c\uc744 \uace0\uce58\uc138\uc694.","\ub098\ub294 \ub9d0\uc500\uc744 \uc5b4\ub5bb\uac8c \ubc1b\uc544\ub4e4\uc774\uace0 \uc788\ub098\uc694?")
B.XI=new A.b1("luke-lesson-9","path-luke","\uc81c\uc790\uc758 \uae38\uacfc \ub530\ub984\uc758 \uc758\ubbf8","\ub204\uac00\ubcf5\uc74c 9\uc7a5","\uc608\uc218\ub2d8\uc740 \uc81c\uc790\ub4e4\uc744 \ubcf4\ub0b4\uc2dc\uba70 \ud558\ub098\ub2d8 \ub098\ub77c\ub97c \uc804\ud558\uac8c \ud558\uc138\uc694. \uc624\ubcd1\uc774\uc5b4 \uae30\uc801\uc744 \ud1b5\ud574 \ud558\ub098\ub2d8\uc758 \ub2a5\ub825\uc744 \ubcf4\uc5ec\uc8fc\uc2dc\uace0 \ubca0\ub4dc\ub85c\ub294 \uc608\uc218\ub2d8\uc744 \uadf8\ub9ac\uc2a4\ub3c4\ub85c \uace0\ubc31\ud574\uc694.","\ub098\ub294 \uc608\uc218\ub2d8\uc744 \ub204\uad6c\ub77c\uace0 \uace0\ubc31\ud558\uace0 \uc788\ub098\uc694?")
B.XG=new A.b1("luke-lesson-10","path-luke","\uc0ac\ub791\uacfc \uc12c\uae40\uc758 \uc0b6","\ub204\uac00\ubcf5\uc74c 10\uc7a5","\uc608\uc218\ub2d8\uc740 70\uc778\uc744 \ubcf4\ub0b4\uc2dc\uba70 \ubcf5\uc74c\uc744 \uc804\ud558\uac8c \ud558\uc138\uc694. \uc0ac\uc5ed\uc744 \ud1b5\ud574 \uae30\uc068\uc744 \uacbd\ud5d8\ud558\uc9c0\ub9cc \uc608\uc218\ub2d8\uc740 \ud558\ub098\ub2d8\uacfc\uc758 \uad00\uacc4\ub97c \ub354 \uc911\uc694\ud558\uac8c \ub9d0\uc500\ud558\uc138\uc694.","\ub098\ub294 \uc9c4\uc9dc\ub85c \uc0ac\ub791\uc744 \uc2e4\ucc9c\ud558\uace0 \uc788\ub098\uc694?")
B.WC=new A.b1("luke-lesson-11","path-luke","\uae30\ub3c4\uc640 \ub9c8\uc74c\uc758 \uc0c1\ud0dc","\ub204\uac00\ubcf5\uc74c 11\uc7a5","\uc608\uc218\ub2d8\uc740 \uc81c\uc790\ub4e4\uc5d0\uac8c \uae30\ub3c4\ub97c \uac00\ub974\uce58\uc2dc\uba70 \ud558\ub098\ub2d8\uacfc\uc758 \uad00\uacc4\ub97c \ubcf4\uc5ec\uc8fc\uc138\uc694. \uad6c\ud558\uace0 \ucc3e\uace0 \ub450\ub4dc\ub9ac\ub77c\uace0 \ub9d0\uc500\ud558\uc2dc\uba70 \ub048\uc9c8\uae34 \uae30\ub3c4\uc758 \uc911\uc694\uc131\uc744 \uac15\uc870\ud558\uc138\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\uacfc \ub300\ud654\ud558\uba70 \uc0b4\uace0 \uc788\ub098\uc694?")
B.Xy=new A.b1("luke-lesson-12","path-luke","\ub450\ub824\uc6c0\uc774 \uc544\ub2cc \ud558\ub098\ub2d8\uc744 \ubc14\ub77c\ubcf4\ub294 \uc0b6","\ub204\uac00\ubcf5\uc74c 12\uc7a5","\uc608\uc218\ub2d8\uc740 \uc678\uc2dd\uacfc \uc704\uc120\uc744 \uacbd\uace0\ud558\uc2dc\uba70 \ud558\ub098\ub2d8 \uc55e\uc5d0\uc11c \ub4dc\ub7ec\ub0a0 \uac83\uc744 \ub9d0\uc500\ud558\uc138\uc694. \uc0ac\ub78c\uc744 \ub450\ub824\uc6cc\ud558\uc9c0 \ub9d0\uace0 \ud558\ub098\ub2d8\uc744 \ub450\ub824\uc6cc\ud558\ub77c\uace0 \uac00\ub974\uce58\uc138\uc694.","\ub098\ub294 \ubb34\uc5c7\uc744 \uac00\uc7a5 \ub450\ub824\uc6cc\ud558\uace0 \uc788\ub098\uc694?")
B.X1=new A.b1("luke-lesson-13","path-luke","\ud68c\uac1c\uc640 \ud558\ub098\ub2d8 \ub098\ub77c\uc758 \uc131\uc7a5","\ub204\uac00\ubcf5\uc74c 13\uc7a5","\uc608\uc218\ub2d8\uc740 \ud68c\uac1c\ud558\uc9c0 \uc54a\uc73c\uba74 \uba78\ub9dd\ud560 \uc218\ubc16\uc5d0 \uc5c6\ub2e4\uace0 \ub9d0\uc500\ud558\uc138\uc694. \uc5f4\ub9e4 \ub9fa\uc9c0 \ubabb\ud558\ub294 \ubb34\ud654\uacfc\ub098\ubb34 \ube44\uc720\ub97c \ud1b5\ud574 \uae30\ud68c\ub97c \uc8fc\uc2dc\ub294 \ud558\ub098\ub2d8\uc758 \uc778\ub0b4\ub97c \ubcf4\uc5ec\uc8fc\uc138\uc694.","\ub098\ub294 \uc9c0\uae08 \ubcc0\ud654\ub418\uace0 \uc788\ub098\uc694?")
B.X2=new A.b1("luke-lesson-14","path-luke","\uacb8\uc190\uacfc \uc81c\uc790\uc758 \ub300\uac00","\ub204\uac00\ubcf5\uc74c 14\uc7a5","\uc608\uc218\ub2d8\uc740 \uc794\uce58 \uc790\ub9ac\uc5d0\uc11c \uacb8\uc190\ud568\uc744 \uac00\ub974\uce58\uc138\uc694. \ub0ae\uc740 \uc790\ub97c \ucd08\ub300\ud558\ub77c\uace0 \ud558\uc2dc\uba70 \ud558\ub098\ub2d8 \ub098\ub77c\uc758 \uac00\uce58\uad00\uc744 \ubcf4\uc5ec\uc8fc\uc138\uc694.","\ub098\ub294 \uacb8\uc190\ud55c \ud0dc\ub3c4\ub85c \uc0b4\uace0 \uc788\ub098\uc694?")
B.Xk=new A.b1("luke-lesson-15","path-luke","\uc783\uc740 \uc790\ub97c \ucc3e\uc73c\uc2dc\ub294 \ud558\ub098\ub2d8","\ub204\uac00\ubcf5\uc74c 15\uc7a5","\uc608\uc218\ub2d8\uc740 \uc783\uc740 \uc591, \uc783\uc740 \ub4dc\ub77c\ud06c\ub9c8, \ub3cc\uc544\uc628 \uc544\ub4e4\uc758 \ube44\uc720\ub97c \ud1b5\ud574 \ud558\ub098\ub2d8\uc758 \ub9c8\uc74c\uc744 \ubcf4\uc5ec\uc8fc\uc138\uc694. \ud558\ub098\ub2d8\uc740 \ud55c \uc0ac\ub78c\uc774\ub77c\ub3c4 \uc783\uc5b4\ubc84\ub9ac\uc9c0 \uc54a\uc73c\uc2dc\uace0 \ub05d\uae4c\uc9c0 \ucc3e\uc73c\uc138\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\uaed8 \ub3cc\uc544\uac00\uace0 \uc788\ub098\uc694?")
B.Xi=new A.b1("luke-lesson-16","path-luke","\uc7ac\ubb3c\uacfc \uc601\uc6d0\ud55c \uac00\uce58","\ub204\uac00\ubcf5\uc74c 16\uc7a5","\uc608\uc218\ub2d8\uc740 \ubd88\uc758\ud55c \uccad\uc9c0\uae30\uc758 \ube44\uc720\ub97c \ud1b5\ud574 \uc9c0\ud61c\ub86d\uac8c \uc0b4\uc544\uc57c \ud568\uc744 \uac00\ub974\uce58\uc138\uc694. \uc7ac\ubb3c\uc740 \uc601\uc6d0\ud558\uc9c0 \uc54a\uc73c\uba70 \ud558\ub098\ub2d8\uacfc \uc7ac\ubb3c\uc744 \ub3d9\uc2dc\uc5d0 \uc12c\uae38 \uc218 \uc5c6\ub2e4\uace0 \ub9d0\uc500\ud558\uc138\uc694.","\ub098\ub294 \ubb34\uc5c7\uc744 \uac00\uc7a5 \uc911\uc694\ud558\uac8c \uc5ec\uae30\uace0 \uc788\ub098\uc694?")
B.X8=new A.b1("luke-lesson-17","path-luke","\uac10\uc0ac\uc640 \ud558\ub098\ub2d8 \ub098\ub77c\uc758 \uc778\uc2dd","\ub204\uac00\ubcf5\uc74c 17\uc7a5","\uc608\uc218\ub2d8\uc740 \uc6a9\uc11c\uc640 \ubbff\uc74c\uc758 \uc911\uc694\uc131\uc744 \uac00\ub974\uce58\uc138\uc694. \uc5f4 \uba85\uc758 \ub098\ubcd1\ud658\uc790\uac00 \uace0\uce68\uc744 \ubc1b\uc9c0\ub9cc \uc624\uc9c1 \ud55c \uc0ac\ub78c\ub9cc \ub3cc\uc544\uc640 \uac10\uc0ac\ud574\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\uaed8 \uac10\uc0ac\ud558\uba70 \uc0b4\uace0 \uc788\ub098\uc694?")
B.WO=new A.b1("luke-lesson-18","path-luke","\uacb8\uc190\uacfc \ub048\uae30 \uc788\ub294 \ubbff\uc74c","\ub204\uac00\ubcf5\uc74c 18\uc7a5","\uc608\uc218\ub2d8\uc740 \ub048\uc9c8\uae30\uac8c \uad6c\ud558\ub294 \uacfc\ubd80\uc758 \ube44\uc720\ub97c \ud1b5\ud574 \uae30\ub3c4\uc758 \uc911\uc694\uc131\uc744 \uac00\ub974\uce58\uc138\uc694. \ubc14\ub9ac\uc0c8\uc778\uacfc \uc138\ub9ac\uc758 \uae30\ub3c4\ub97c \ud1b5\ud574 \uacb8\uc190\ud55c \ud0dc\ub3c4\uac00 \ud558\ub098\ub2d8\uaed8 \ubc1b\uc544\ub4e4\uc5ec\uc9c4\ub2e4\uace0 \ub9d0\uc500\ud558\uc138\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\uaed8 \uacc4\uc18d \ub098\uc544\uac00\uace0 \uc788\ub098\uc694?")
B.WP=new A.b1("luke-lesson-19","path-luke","\ud68c\uac1c\uc640 \ucc45\uc784 \uadf8\ub9ac\uace0 \uc655 \ub418\uc2e0 \uc608\uc218\ub2d8","\ub204\uac00\ubcf5\uc74c 19\uc7a5","\uc0ad\uac1c\uc624\ub294 \uc608\uc218\ub2d8\uc744 \ub9cc\ub098 \uc0b6\uc774 \uc644\uc804\ud788 \ubcc0\ud654\ub3fc\uc694. \uc608\uc218\ub2d8\uc740 \uc783\uc740 \uc790\ub97c \ucc3e\uc544 \uad6c\uc6d0\ud558\ub7ec \uc624\uc168\ub2e4\uace0 \ub9d0\uc500\ud558\uc138\uc694.","\ub098\ub294 \ubcc0\ud654\ub41c \uc0b6\uc744 \uc0b4\uace0 \uc788\ub098\uc694?")
