B.X5=new A.b1("john-lesson-1","path-john","\ub9d0\uc500\uc774\uc2e0 \uc608\uc218\ub2d8\uacfc \ube5b","\uc694\ud55c\ubcf5\uc74c 1\uc7a5",'\uc694\ud55c\ubcf5\uc74c\uc740 \uc608\uc218\ub2d8\uc744 "\ub9d0\uc500"\uc73c\ub85c \uc18c\uac1c\ud558\uba70 \uc2dc\uc791\ud574\uc694. \uc774 \ub9d0\uc500\uc740 \ud558\ub098\ub2d8\uacfc \ud568\uaed8 \uacc4\uc168\uace0 \uace7 \ud558\ub098\ub2d8\uc774\uc168\uc5b4\uc694. \uc608\uc218\ub2d8\uc740 \uc138\uc0c1\uc758 \ube5b\uc73c\ub85c \uc624\uc168\uc9c0\ub9cc \uc0ac\ub78c\ub4e4\uc740 \uadf8 \ube5b\uc744 \uc54c\uc544\ubcf4\uc9c0 \ubabb\ud588\uc5b4\uc694. \uadf8\ub7ec\ub098 \uc608\uc218\ub2d8\uc744 \uc601\uc811\ud55c \uc0ac\ub78c\ub4e4\uc5d0\uac8c\ub294 \ud558\ub098\ub2d8\uc758 \uc790\ub140\uac00 \ub418\ub294 \uad8c\uc138\uac00 \uc8fc\uc5b4\uc838\uc694. \uc774 \uc7a5\uc740 \uc608\uc218\ub2d8\uc774 \ub204\uad6c\uc2e0\uc9c0\uc640 \uadf8\ubd84\uc744 \ubc1b\uc544\ub4e4\uc774\ub294 \uac83\uc774 \uc5bc\ub9c8\ub098 \uc911\uc694\ud55c\uc9c0\ub97c \ubcf4\uc5ec\uc918\uc694.',"\ub098\ub294 \uc608\uc218\ub2d8\uc744 \uc9c4\uc9dc \ubc1b\uc544\ub4e4\uc774\uace0 \uc788\ub098\uc694?")
B.X9=new A.b1("john-lesson-2","path-john","\ubcc0\ud654\uc640 \ucc38\ub41c \uc608\ubc30","\uc694\ud55c\ubcf5\uc74c 2\uc7a5","\uc608\uc218\ub2d8\uc740 \uac00\ub098\uc758 \ud63c\uc778\uc794\uce58\uc5d0\uc11c \ubb3c\uc744 \ud3ec\ub3c4\uc8fc\ub85c \ubc14\uafb8\uc2dc\ub294 \uccab \uae30\uc801\uc744 \ud589\ud558\uc138\uc694. \uc774\ub97c \ud1b5\ud574 \uc608\uc218\ub2d8\uc758 \uc601\uad11\uc774 \ub4dc\ub7ec\ub098\uace0 \uc81c\uc790\ub4e4\uc774 \ubbff\uac8c \ub3fc\uc694. \ub610\ud55c \uc131\uc804\uc744 \uae68\ub057\ud558\uac8c \ud558\uc2dc\uba70 \ud558\ub098\ub2d8\uc744 \ud5a5\ud55c \ucc38\ub41c \uc608\ubc30\ub97c \uac15\uc870\ud558\uc138\uc694. \uc0ac\ub78c\ub4e4\uc740 \ud45c\uc801\uc744 \ubcf4\uace0 \ubbff\uc73c\ub824 \ud558\uc9c0\ub9cc \uc608\uc218\ub2d8\uc740 \uc911\uc2ec\uc744 \ubcf4\uc138\uc694. \uc774 \uc7a5\uc740 \ubcc0\ud654\uc640 \uc608\ubc30\uc758 \ubcf8\uc9c8\uc744 \ubcf4\uc5ec\uc918\uc694.","\ub098\ub294 \ud558\ub098\ub2d8\uc774 \uc8fc\uc2dc\ub294 \ubcc0\ud654\ub97c \uacbd\ud5d8\ud558\uace0 \uc788\ub098\uc694?")
